1	// Package metrics holds cumulative metric samples: their normalized content,
2	// batch ingestion with de-duplication, and the delta aggregation over aligned
3	// segments. Sample ids are independent of event ids.
4	package metrics
5	
6	import (
7		"errors"
8		"fmt"
9		"maps"
10		"math"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15		"time"
16	
17		"github.com/cocosolocoder/signalroom/internal/events"
18	)
19	
20	// MaxBatchPayloadBytes bounds what one metric save may hold in the on-disk
21	// save format (MarshalBatch): 64 MiB in 1024*1024-byte units, matching the
22	// durable frame capacity. It measures the encoded JSON content of the newly
23	// saved samples only — not any replayed samples, the request body's outer
24	// object, or the surrounding frame header. A batch encoding to exactly this
25	// size is still accepted; only a larger encoding is rejected.
26	const MaxBatchPayloadBytes = 64 << 20
27	
28	// ValidationError reports that a sample failed normalization (or, during
29	// aggregation, that a query was invalid).
30	type ValidationError struct{ Reason string }
31	
32	func (e *ValidationError) Error() string { return e.Reason }
33	
34	// IsValidationError reports whether err is a metrics validation failure.
35	func IsValidationError(err error) bool {
36		var target *ValidationError
37		return errors.As(err, &target)
38	}
39	
40	// ConflictError reports an id clash with different content, a repeated id in
41	// one batch, or a series/time clash between different ids.
42	type ConflictError struct{ Reason string }
43	
44	func (e *ConflictError) Error() string { return e.Reason }
45	
46	// IsConflictError reports whether err is a metrics conflict.
47	func IsConflictError(err error) bool {
48		var target *ConflictError
49		return errors.As(err, &target)
50	}
51	
52	// OversizeBatchError reports that the brand-new samples of a batch encode to
53	// more than MaxBatchPayloadBytes in the save format. It is a property of the
54	// request content, not of the storage: nothing is written, the store stays
55	// usable without a restart, the rejected ids remain free, and the same
56	// samples are accepted once split into smaller submissions. Replayed
57	// samples are not part of the measured payload.
58	type OversizeBatchError struct {
59		Size  int
60		Limit int
61	}
62	
63	func (e *OversizeBatchError) Error() string {
64		return fmt.Sprintf("metric batch saves to %d bytes, exceeding the %d byte per-batch save capacity; split the submission into smaller batches or reduce its content", e.Size, e.Limit)
65	}
66	
67	// IsOversizeBatchError reports whether err is a batch that exceeds the save
68	// capacity, as opposed to a validation, conflict, or storage failure.
69	func IsOversizeBatchError(err error) bool {
70		var target *OversizeBatchError
71		return errors.As(err, &target)
72	}
73	
74	// Sample is one normalized cumulative counter reading. Labels carries the
75	// optional trimmed label set and is nil when the sample has none.
76	type Sample struct {
77		ID      string
78		Service string
79		Name    string
80		At      time.Time
81		Value   float64
82		Labels  map[string]string
83	}
84	
85	// Normalize applies the ingestion rules: trim surrounding whitespace from id,
86	// service, and metric name (their case is kept) and require each non-empty
87	// afterwards; require a non-zero instant; require a non-negative, finite
88	// value; and trim/validate labels with the same rules events use.
89	func Normalize(s Sample) (Sample, error) {
90		s.ID = strings.TrimSpace(s.ID)
91		s.Service = strings.TrimSpace(s.Service)
92		s.Name = strings.TrimSpace(s.Name)
93		if s.ID == "" || s.Service == "" || s.Name == "" || s.At.IsZero() {
94			return Sample{}, &ValidationError{Reason: "sample id, service, name, and timestamp are required"}
95		}
96		if !finiteNonNegative(s.Value) {
97			return Sample{}, &ValidationError{Reason: "value must be a non-negative, finite JSON number"}
98		}
99		labels, err := events.NormalizeLabels(s.Labels)
100		if err != nil {
101			return Sample{}, &ValidationError{Reason: err.Error()}
102		}
103		s.Labels = labels
104		return s, nil
105	}
106	
107	// finiteNonNegative rejects NaN, infinities (which JSON cannot carry anyway),
108	// and negative readings.
109	func finiteNonNegative(v float64) bool {
110		return !math.IsNaN(v) && !math.IsInf(v, 0) && v >= 0
111	}
112	
113	// seriesKey identifies one time series: a metric name within a service plus
114	// the complete label set. Names are compared case-sensitively after trimming.
115	type seriesKey struct {
116		service string
117		name    string
118		labels  string
119	}
120	
121	// pointKey identifies one absolute instant within a series. Unlike
122	// time.Time.UnixNano, which overflows for instants outside 1678–2262 and can
123	// alias two distant times, the (seconds, nanoseconds) pair is exact for every
124	// instant the RFC3339Nano entry points accept, and Unix seconds already
125	// canonicalize timezone offsets so equal instants share one key.
126	type pointKey struct {
127		sec  int64
128		nsec int32
129	}
130	
131	// pointKeyOf renders an instant as its absolute point identity.
132	func pointKeyOf(at time.Time) pointKey {
133		return pointKey{sec: at.Unix(), nsec: int32(at.Nanosecond())}
134	}
135	
136	// BeforeCommit persists a batch of brand-new samples. It runs while the store
137	// lock is held and before the batch becomes visible, so a successful return
138	// guarantees the batch is durable and committed atomically.
139	type BeforeCommit func(persisted []Sample) error
140	
141	// Store is a concurrency-safe set of metric samples grouped into series. It
142	// accepts whole batches and reports retries of already-stored samples.
143	type Store struct {
144		mu     sync.RWMutex
145		byID   map[string]Sample
146		series map[seriesKey]*seriesState
147	}
148	
149	// NewStore returns an empty store.
150	func NewStore() *Store {
151		return &Store{
152			byID:   make(map[string]Sample),
153			series: make(map[seriesKey]*seriesState),
154		}
155	}
156	
157	// IngestResult counts how a batch was applied: Created samples are new,
158	// Replayed samples matched an existing sample with the same id and content.
159	type IngestResult struct {
160		Created  int
161		Replayed int
162	}
163	
164	// Ingest normalizes and validates every sample first, then checks the whole
165	// batch against stored samples and itself. Validation failures produce a
166	// ValidationError; duplicate ids with differing content, a repeated id within
167	// the batch, or a (series, time) clash between different ids produce a
168	// ConflictError. Nothing is stored when an error is returned.
169	//
170	// After those checks, the JSON bytes the brand-new samples would actually
171	// save (MarshalBatch of only the new samples, with the save format's JSON
172	// escaping applied) are measured against MaxBatchPayloadBytes; an oversize
173	// batch produces an OversizeBatchError, still before anything is written.
174	//
175	// New samples are passed to beforeCommit for durable storage; only after it
176	// succeeds does the batch become visible, so concurrent readers see either the
177	// complete batch or none of it, and concurrent batches serialize so the whole
178	// batch either commits or fails.
179	func (s *Store) Ingest(batch []Sample, beforeCommit BeforeCommit) (IngestResult, error) {
180		normalized := make([]Sample, len(batch))
181		for i, sample := range batch {
182			norm, err := Normalize(sample)
183			if err != nil {
184				return IngestResult{}, err
185			}
186			normalized[i] = norm
187		}
188	
189		s.mu.Lock()
190		defer s.mu.Unlock()
191	
192		pendingID := make(map[string]struct{}, len(normalized))
193		pendingPoint := make(map[seriesKey]map[pointKey]string, len(normalized))
194		var created []Sample
195		var result IngestResult
196		for _, sample := range normalized {
197			if _, repeated := pendingID[sample.ID]; repeated {
198				return IngestResult{}, &ConflictError{Reason: "sample id repeats within batch"}
199			}
200			pendingID[sample.ID] = struct{}{}
201	
202			key := keyFor(sample)
203			if existing, ok := s.byID[sample.ID]; ok {
204				if !sameContent(existing, sample) {
205					return IngestResult{}, &ConflictError{Reason: "sample id already exists with different content"}
206				}
207				// An id retry must never mask another id's point.
208				if owner := s.series[key].pointOwner(sample.At); owner != "" && owner != sample.ID {
209					return IngestResult{}, &ConflictError{
210						Reason: "sample collides with a different sample of the same series at the same time"}
211				}
212				result.Replayed++
213				continue
214			}
215	
216			// A brand-new id must not claim a (series, time) point already stored
217			// under another id.
218			if owner := s.series[key].pointOwner(sample.At); owner != "" {
219				return IngestResult{}, &ConflictError{
220					Reason: "sample collides with a different sample of the same series at the same time"}
221			}
222			// Nor one introduced earlier in this same batch.
223			if owners := pendingPoint[key]; owners != nil {
224				if owner, dup := owners[pointKeyOf(sample.At)]; dup && owner != sample.ID {
225					return IngestResult{}, &ConflictError{
226						Reason: "sample collides with a different sample of the same series at the same time"}
227				}
228			}
229			created = append(created, sample)
230			result.Created++
231			if pendingPoint[key] == nil {
232				pendingPoint[key] = make(map[pointKey]string)
233			}
234			pendingPoint[key][pointKeyOf(sample.At)] = sample.ID
235		}
236	
237		if len(created) > 0 {
238			// Only brand-new samples are saved, so only they count toward the save
239			// capacity: a batch made entirely (or partly) of identical retries is
240			// measured by what would actually be written. The check runs after
241			// validation and conflict checks but before beforeCommit, so an
242			// oversize batch neither touches durable storage nor marks metric
243			// storage unavailable.
244			payload, err := MarshalBatch(created)
245			if err != nil {
246				return IngestResult{}, err
247			}
248			if len(payload) > MaxBatchPayloadBytes {
249				return IngestResult{}, &OversizeBatchError{Size: len(payload), Limit: MaxBatchPayloadBytes}
250			}
251			if beforeCommit != nil {
252				if err := beforeCommit(created); err != nil {
253					return IngestResult{}, err
254				}
255			}
256			for _, sample := range created {
257				s.byID[sample.ID] = sample
258				key := keyFor(sample)
259				state := s.series[key]
260				if state == nil {
261					state = &seriesState{labels: sample.Labels}
262					s.series[key] = state
263				}
264				state.add(sample)
265			}
266		}
267		return result, nil
268	}
269	
270	// Load inserts samples recovered from durable storage during startup. Every
271	// sample must already be normalized; a contradictory record is reported as a
272	// conflict so the caller can fail rather than mutate data.
273	func (s *Store) Load(sample Sample) error {
274		if _, err := Normalize(sample); err != nil {
275			return err
276		}
277		s.mu.Lock()
278		defer s.mu.Unlock()
279		key := keyFor(sample)
280		if existing, ok := s.byID[sample.ID]; ok {
281			if !sameContent(existing, sample) {
282				return &ConflictError{Reason: "sample id already exists with different content"}
283			}
284			return nil
285		}
286		if owner := s.series[key].pointOwner(sample.At); owner != "" {
287			return &ConflictError{Reason: "sample collides with a different sample of the same series at the same time"}
288		}
289		s.byID[sample.ID] = sample
290		state := s.series[key]
291		if state == nil {
292			state = &seriesState{labels: sample.Labels}
293			s.series[key] = state
294		}
295		state.add(sample)
296		return nil
297	}
298	
299	// keyFor builds the identity of a series from a normalized sample.
300	func keyFor(sample Sample) seriesKey {
301		return seriesKey{service: sample.Service, name: sample.Name, labels: labelsKey(sample.Labels)}
302	}
303	
304	// labelsKey renders a label set as a collision-free canonical string so two
305	// maps with the same complete set share a series regardless of iteration
306	// order. Name and value are each length-prefixed, which keeps values
307	// containing '=' or ';' from ever aliasing another set.
308	func labelsKey(labels map[string]string) string {
309		if len(labels) == 0 {
310			return ""
311		}
312		keys := make([]string, 0, len(labels))
313		for name := range labels {
314			keys = append(keys, name)
315		}
316		sort.Strings(keys)
317		var b strings.Builder
318		for _, name := range keys {
319			value := labels[name]
320			b.WriteString(strconv.Itoa(len(name)))
321			b.WriteByte(':')
322			b.WriteString(name)
323			b.WriteByte(',')
324			b.WriteString(strconv.Itoa(len(value)))
325			b.WriteByte(':')
326			b.WriteString(value)
327			b.WriteByte(';')
328		}
329		return b.String()
330	}
331	
332	// seriesState is one sorted run of (time, value, id) points sharing one
333	// label set.
334	type seriesState struct {
335		labels map[string]string
336		points []point
337	}
338	
339	type point struct {
340		at    time.Time
341		value float64
342		id    string
343	}
344	
345	// add inserts one point keeping the run ordered by time. Points at the same
346	// instant for one series are rejected upstream.
347	func (st *seriesState) add(sample Sample) {
348		p := point{at: sample.At, value: sample.Value, id: sample.ID}
349		idx := sort.Search(len(st.points), func(i int) bool {
350			return st.points[i].at.After(p.at)
351		})
352		st.points = append(st.points, point{})
353		copy(st.points[idx+1:], st.points[idx:])
354		st.points[idx] = p
355	}
356	
357	// pointOwner returns the id of the sample at exactly at, or "" when the point
358	// is absent. A nil receiver reports no owner.
359	func (st *seriesState) pointOwner(at time.Time) string {
360		if st == nil {
361			return ""
362		}
363		idx := sort.Search(len(st.points), func(i int) bool {
364			return !st.points[i].at.Before(at)
365		})
366		if idx < len(st.points) && st.points[idx].at.Equal(at) {
367			return st.points[idx].id
368		}
369		return ""
370	}
371	
372	// sameContent compares two normalized samples on their absolute instant,
373	// value, and label set. Numeric equality makes 1 and 1.0 identical; map
374	// comparison makes label key order irrelevant.
375	func sameContent(a, b Sample) bool {
376		return a.ID == b.ID &&
377			a.Service == b.Service &&
378			a.Name == b.Name &&
379			a.At.Equal(b.At) &&
380			a.Value == b.Value &&
381			maps.Equal(a.Labels, b.Labels)
382	}
