1	// Package logfile persists event batches as an append-only sequence of
2	// length-prefixed, CRC-checked frames.
3	//
4	// Frame layout (all integers big-endian):
5	//
6	//	[4 bytes payload length][4 bytes CRC32-IEEE of payload][payload bytes]
7	//
8	// The payload is a JSON array encoded with events.MarshalBatch.
9	package logfile
10	
11	import (
12		"errors"
13		"fmt"
14		"os"
15		"path/filepath"
16	
17		"github.com/cocosolocoder/signalroom/internal/events"
18	)
19	
20	const (
21		logName  = "events.log"
22		lockName = "lock"
23	)
24	
25	// Log is an append-only, concurrency-safe frame writer holding an exclusive
26	// directory lock for its lifetime.
27	type Log struct {
28		*frameLog
29		lockFile *os.File
30		key      []byte
31	}
32	
33	// Open acquires an exclusive lock on the data directory, creates it if
34	// needed, replays the log, and truncates at most one incomplete trailing
35	// frame (a torn final write). A corrupt frame in the middle, a complete
36	// frame containing illegal data, or two complete records carrying the same
37	// event id with different normalized content, is fatal: Open returns an
38	// error without modifying the file, torn tail included.
39	//
40	// Recovered batches are returned in write order, ready to load into a
41	// timeline.
42	func Open(dir string) (*Log, [][]events.Event, error) {
43		if dir == "" {
44			return nil, nil, errors.New("data directory is required")
45		}
46		if err := os.MkdirAll(dir, 0o755); err != nil {
