153		if err := mLog.Append([]metrics.Sample{metricSample("x", 11, 1)}); err == nil {
154			t.Fatal("write to a closed file must fail")
155		}
156		if !mLog.Poisoned() {
157			t.Fatal("log must be poisoned after a write failure")
158		}
159		if err := mLog.Append([]metrics.Sample{metricSample("y", 12, 1)}); err == nil {
