		t.Fatalf("append: %v", err)
	}
	if err := mLog.Append([]metrics.Sample{metricSample("m3", 12, 3)}); err != nil {
		t.Fatalf("append: %v", err)
	}

	if err := mLog.Close(); err != nil {
		t.Fatal(err)
	}
	if err := eventLog.Close(); err != nil {
		t.Fatal(err)
	}

	eventLog, mLog, batches = openMetricsForTest(t, dir)
	defer eventLog.Close()
	defer mLog.Close()
	if len(batches) != 2 || len(batches[0]) != 2 || len(batches[1]) != 1 {
		t.Fatalf("recovered shape: %+v", batches)
	}
	if batches[0][0].ID != "m1" || batches[1][0].Value != 3 {
		t.Fatalf("recovered content: %+v", batches)
	}
}

func TestMetricsLogTrimsTornTail(t *testing.T) {
	dir := t.TempDir()
	eventLog, mLog, _ := openMetricsForTest(t, dir)
	if err := mLog.Append([]metrics.Sample{metricSample("good", 10, 1)}); err != nil {
		t.Fatal(err)
	}
	mLog.Close()
	eventLog.Close()

	path := filepath.Join(dir, metricsLogName)
	existing, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	payload := []byte(`[{"id":"torn","service":"gw","name":"requests","at":"2026-10-01T00:00:11Z","value":2}]`)
	torn := make([]byte, headerSize+4)
	putFrameHeader(torn, payload)
	copy(torn[headerSize:], payload[:4])
	if err := os.WriteFile(path, append(append([]byte(nil), existing...), torn...), 0o644); err != nil {
		t.Fatal(err)
	}

	eventLog2, mLog2, batches := openMetricsForTest(t, dir)
	defer eventLog2.Close()
	defer mLog2.Close()
	if len(batches) != 1 || batches[0][0].ID != "good" {
		t.Fatalf("torn tail must be trimmed, recovered: %+v", batches)
	}
}

func TestMetricsLogFailsOnMidCorruption(t *testing.T) {
	dir := t.TempDir()
	eventLog, mLog, _ := openMetricsForTest(t, dir)
	if err := mLog.Append([]metrics.Sample{metricSample("good", 10, 1)}); err != nil {
		t.Fatal(err)
	}
	mLog.Close()
	eventLog.Close()

	path := filepath.Join(dir, metricsLogName)
	original, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	firstLen := headerSize + int(framePrefixLen(original[0:4]))
	payload := []byte(`[{"id":"bad","service":"gw","name":"requests","at":"2026-10-01T00:00:11Z","value":2}]`)
	bad := make([]byte, headerSize+len(payload))
	putFrameHeader(bad, payload)
	copy(bad[headerSize:], payload)
	bad[headerSize] ^= 0xFF // checksum mismatch in a complete middle frame
	corrupt := append(original[:firstLen], bad...)
	if err := os.WriteFile(path, corrupt, 0o644); err != nil {
		t.Fatal(err)
	}

	eventLog2, _, openErr := Open(dir)
	if openErr != nil {
		t.Fatalf("event log must still open: %v", openErr)
	}
	defer eventLog2.Close()
	if _, _, err := OpenMetricsLog(dir); err == nil {
		t.Fatal("corrupt metrics log must prevent startup")
	}

	// The corrupt bytes must be left untouched.
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if string(after) != string(corrupt) {
		t.Fatal("failed startup must not modify the corrupt data")
	}
}

func TestMetricsLogFailurePoisons(t *testing.T) {
	dir := t.TempDir()
	eventLog, mLog, _ := openMetricsForTest(t, dir)
	defer eventLog.Close()
	defer mLog.Close()
	if err := mLog.Append([]metrics.Sample{metricSample("m", 10, 1)}); err != nil {
		t.Fatal(err)
	}
	if err := mLog.file.Close(); err != nil {
		t.Fatal(err)
	}
	// The next write must fail and poison every subsequent call.
	if err := mLog.Append([]metrics.Sample{metricSample("x", 11, 1)}); err == nil {
		t.Fatal("write to a closed file must fail")
	}
	if !mLog.Poisoned() {
		t.Fatal("log must be poisoned after a write failure")
	}
	if err := mLog.Append([]metrics.Sample{metricSample("y", 12, 1)}); err == nil {
		t.Fatal("poisoned log must keep failing")
	}
}

package logfile

import (
	"fmt"

	"github.com/cocosolocoder/signalroom/internal/incidents"
)

// incidentLogName is the append-only record log for incidents. It sits next
// to events.log in the locked data directory and uses the same
// length-prefixed, CRC-checked frame layout, so the durability and recovery
// rules are identical: fsync before acknowledging, trim only a torn tail,
// and refuse to start on any other corruption.
const incidentLogName = "incidents.log"

// IncidentLog is the concurrency-safe durable writer for incident records.
// It is independent from the event log: an incident write failure poisons
// only incident handling, exactly as an event write failure poisons only
// event ingestion.
type IncidentLog struct {
	*frameLog
}

// OpenIncidentLog opens (creating if absent) the incident log inside an
// already-locked data directory, replays its records, and truncates at most
// one incomplete trailing frame. A corrupt frame in the middle, or a
// complete frame containing illegal data, is fatal and leaves the file
// untouched. Call it only after Open has acquired the directory lock.
func OpenIncidentLog(dir string) (*IncidentLog, []incidents.Record, error) {
	if dir == "" {
		return nil, nil, fmt.Errorf("data directory is required")
	}
	base, records, err := openFrameLog(dir, incidentLogName, "incident", "incident record", incidents.DecodeRecord, nil)
	if err != nil {
		return nil, nil, err
	}
	return &IncidentLog{frameLog: base}, records, nil
}

// AppendRecord durably writes one record: the frame is written and fsynced
// before the call returns. Any write or sync failure poisons the log so that
// this call and every later one fail until restart.
func (l *IncidentLog) AppendRecord(record incidents.Record) error {
	payload, err := incidents.MarshalRecord(record)
	if err != nil {
		return fmt.Errorf("encode incident record: %w", err)
	}
	return l.appendFrame(payload)
}

