139				if err := dec.Decode(&value); err != nil {
140					return rawSample{}, fmt.Errorf("decode sample: %s must be a string", key)
141				}
142				switch key {
143				case "id":
144					raw.id = value
145				case "service":
146					raw.service = value
147				case "name":
