7		"github.com/cocosolocoder/signalroom/internal/metrics"
8	)
9	
10	// metricsLogName is the append-only batch log for metric samples. It sits
11	// next to events.log in the locked data directory and uses the same
12	// length-prefixed, CRC-checked frame layout, so the durability and recovery
13	// rules are identical: fsync before acknowledging, trim only a torn tail,
14	// and refuse to start on any other corruption.
15	const metricsLogName = "metrics.log"
16	
17	// MetricsLog is the concurrency-safe durable writer for metric batches. It is
18	// independent from both the event and incident logs: a metric write failure
19	// poisons only metric handling, leaving events and incidents available.
20	type MetricsLog struct {
21		*frameLog
22	}
23	
24	// OpenMetricsLog opens (creating if absent) the metrics log inside an
25	// already-locked data directory, replays its batches, and truncates at most
26	// one incomplete trailing frame. A corrupt frame in the middle, or a complete
27	// frame containing illegal data, is fatal and leaves the file untouched. So
28	// is a conflict between complete, legal records — the same id with different
29	// normalized content, or two different ids claiming one (series, time)
30	// point, inside one batch or across batches — and that check runs before the
31	// torn tail is trimmed, so a conflicting log keeps every byte including the
32	// unfinished suffix. Call it only after Open has acquired the directory
33	// lock.
34	func OpenMetricsLog(dir string) (*MetricsLog, [][]metrics.Sample, error) {
35		if dir == "" {
36			return nil, nil, fmt.Errorf("data directory is required")
37		}
38		base, batches, err := openFrameLog(dir, metricsLogName, "metrics", "metric batch", decodeMetricBatch, checkMetricConflicts)
39		if err != nil {
40			return nil, nil, err
41		}
42		return &MetricsLog{frameLog: base}, batches, nil
43	}
44	
45	// checkMetricConflicts rejects a recovered log whose complete, validated
46	// records contradict each other: the same sample id carrying different
47	// normalized content, or two different ids occupying one sampling instant of
48	// one series (service, metric name, complete label set), whether the clash
49	// sits inside one batch or across batches. It reuses the store's own recovery
50	// rules, so the comparison matches what serving would apply: identical id
51	// retries collapse to one copy, timezone/label-order/whitespace spellings and
52	// 1 vs 1.0 never clash, while a one-nanosecond instant move or a different
53	// label set does. It runs before any torn-tail truncation, so a conflicting
54	// log keeps every byte it had before startup.
55	func checkMetricConflicts(batches [][]metrics.Sample) error {
56		recovered := metrics.NewStore()
57		for _, batch := range batches {
58			for _, sample := range batch {
59				if err := recovered.Load(sample); err != nil {
60					return fmt.Errorf("metric history contains conflicting samples: %w", err)
61				}
62			}
63		}
64		return nil
65	}
66	
67	// decodeMetricBatch decodes one frame payload into a validated, normalized
68	// metric batch. An empty batch or an invalid sample is rejected as
69	// corruption.
70	func decodeMetricBatch(payload []byte) ([]metrics.Sample, error) {
71		batch, err := metrics.DecodeBatch(payload)
72		if err != nil {
73			return nil, err
74		}
75		if len(batch) == 0 {
76			return nil, errors.New("empty metric batch frame")
77		}
78		for i := range batch {
79			normalized, err := metrics.Normalize(batch[i])
80			if err != nil {
81				return nil, err
82			}
83			batch[i] = normalized
84		}
85		return batch, nil
86	}
87	
88	// Append durably writes one batch: the frame is written and fsynced before the
89	// call returns. Any write or sync failure poisons the log so that this call
90	// and every later one fail until restart.
91	func (l *MetricsLog) Append(batch []metrics.Sample) error {
92		payload, err := metrics.MarshalBatch(batch)
93		if err != nil {
94			return fmt.Errorf("encode metric batch: %w", err)
95		}
96		return l.appendFrame(payload)
97	}
